<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Models\Category;use Illuminate\Http\Request;use Illuminate\Support\Str;
class CategoryController extends Controller { public function index(){return view('admin.categories.index',['categories'=>Category::withCount('products')->latest()->get()]);} public function store(Request $r){$d=$r->validate(['name'=>'required|string|max:100|unique:categories,name','description'=>'nullable|string','is_active'=>'nullable|boolean']);$d['slug']=Str::slug($d['name']);$d['is_active']=$r->boolean('is_active');Category::create($d);return back()->with('status','Category created.');} public function update(Request $r,Category $category){$d=$r->validate(['name'=>'required|string|max:100|unique:categories,name,'.$category->id,'description'=>'nullable|string','is_active'=>'nullable|boolean']);$d['slug']=Str::slug($d['name']);$d['is_active']=$r->boolean('is_active');$category->update($d);return back()->with('status','Category updated.');} public function destroy(Category $category){if($category->products()->exists())return back()->withErrors(['category'=>'Products must be reassigned before deleting this category.']);$category->delete();return back()->with('status','Category deleted.');}}
